   /**
    * 获取统计图查看明细dwContext参数
    */
   public RptViewDwContext getStatDetailDwContextArg(List<com.facishare.bi.common.dto.filter.FilterList> viewDetailFiltersList,
                                                     List<DisplayField> displayFields,
                                                     AggRuleDOEXT aggRuleDOEXT,
                                                     String timeZone,
                                                     String rptMainObjName,
                                                     List<AggAuthField> aggAuthFieldInfo) {
     BiMtTopologyDescribeDO aggRuleTopologyDescribe = aggRuleCovertService.getAggRuleTopologyDescribe(aggRuleDOEXT, timeZone, rptMainObjName);
     Map<String, String> nodeInfoMap = getNodeInfoMap(aggRuleTopologyDescribe);
     String checkObjNodeId = getCheckObjNodeId(aggRuleDOEXT, nodeInfoMap);
     validateNodeRelation(aggRuleTopologyDescribe);
     handleAggAuthFieldInfo(aggAuthFieldInfo, nodeInfoMap, rptMainObjName);
     RptViewDwContext rptViewDwContext = new RptViewDwContext();
     rptViewDwContext.setBiMtTopologyDescribeDO(aggRuleTopologyDescribe);
     rptViewDwContext.setBiMtDetailDOList(displayFieldsToBiMtDetailDOList(displayFields, viewDetailFiltersList, aggRuleTopologyDescribe.getTopologyDescribeId(), nodeInfoMap, checkObjNodeId));
     rptViewDwContext.setTenantId(RequestContextManagerBase.getEi());
     rptViewDwContext.setAggAuthFieldList(aggAuthFieldInfo);
     return rptViewDwContext;
   }

   /**
    * 验证节点关系
    */
   private void validateNodeRelation(BiMtTopologyDescribeDO aggRuleTopologyDescribe) {
     String topologyModel = aggRuleTopologyDescribe.getTopologyModel();
     JSONObject topologyJsonObject = JSON.parseObject(topologyModel);
     JSONArray nodes = topologyJsonObject.getJSONArray("nodes");
     JSONArray edges = topologyJsonObject.getJSONArray("edges");
     //查看明细暂时只支持一条线的对象关系
     if (nodes.size() > 3) {
       log.warn("topology mode node size more than 3, not support view detail.");
-      throw new BIBizException(I18NErrorCodeEnum.STAT_DETAIL_UNSUPPORTED.getErrorCode(), 403,
-        I18NMsgEnum.I18NMessageEnum.STAT_MODEL_DETAIL_UNSUPPORTED.getI18nLabel("0", I18NUtil.getLangTag()));
+      throw new BIBizException(I18NErrorCodeEnum.MULTI_RELATION_METRIC_DETAIL_UNSUPPORTED.getErrorCode(), 403, "");
     }
     List<String> fromNodeIds = Lists.newArrayList();
     List<String> toNodeIds = Lists.newArrayList();
     List<AggRuleCovertService.EdgeItem> edgeItemList = JSONArray.parseArray(edges.toJSONString(), AggRuleCovertService.EdgeItem.class);
     for (AggRuleCovertService.EdgeItem edgeItem : edgeItemList) {
       String from = edgeItem.getFrom();
       String to = edgeItem.getTo();
       if (fromNodeIds.contains(from) || toNodeIds.contains(to)) {
         log.warn("topology mode node relation not support, topologyModel:{}", topologyModel);
         throw new StatDetailDegradeException("topology mode node relation not support");
       }
       fromNodeIds.add(from);
       toNodeIds.add(to);
     }
   }

   /**
    * 处理指标权限字段信息
    */
   private void handleAggAuthFieldInfo(List<AggAuthField> aggAuthFieldInfo,
                                       Map<String, String> nodeInfoMap,
                                       String rptMainObjName) {
     if (CollectionUtils.isEmpty(aggAuthFieldInfo) || MapUtils.isEmpty(nodeInfoMap)) {
       return;
     }
     for (AggAuthField aggAuthField : aggAuthFieldInfo) {
       String authObjName = aggAuthField.getAuthObjName();
       String authSql = aggAuthField.getAuthSql();
       aggAuthField.setAuthSql(PreSqlCHBDWhereSceneFlowNode.getClickHouseSql(authSql));
       String selfRelationAuthObjName = authObjName + "_";
       //如果权限对象是报表主对象一样，说明权限对象是自关联对象（考核主题本对象指标不会把主题对象放到指标权限对象中）
       if (Objects.equal(rptMainObjName, authObjName) && nodeInfoMap.containsKey(selfRelationAuthObjName)) {
         aggAuthField.setAuthObjName(nodeInfoMap.get(selfRelationAuthObjName));
         continue;
       }
       if (nodeInfoMap.containsKey(authObjName)) {
         aggAuthField.setAuthObjName(nodeInfoMap.get(authObjName));
       }
     }
   }

